<script setup lang="ts">
import {onMounted,onBeforeUnmount,reactive,ref,computed,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {scanModelCheckpoints,createModelImport,getModelImport,listModelImports,controlModelImport,importLabels,importActive} from '../api/modelImports'
import type {ModelImport,ImportedCheckpoint} from '../types'
import {useDemoStore} from '../stores/demo'
const route=useRoute(),router=useRouter(),store=useDemoStore()
const form=reactive({weightMode:'base',selectedCheckpoints:[] as string[],mode:'add',sourceCode:'',sourceWeights:'',sourceEnvironment:'',name:'',github:'',weights:'',revision:'',python:'python3'})
const root=ref('加载管理目录…'),current=ref<ModelImport|null>(null),error=ref(''),busy=ref(false),available=ref(false)
let timer:ReturnType<typeof setTimeout>|undefined,disposed=false
const candidates=ref<ImportedCheckpoint[]>([]),scanning=ref(false),scanError=ref(''),scanned=ref(false)
watch(()=>[form.sourceWeights,form.sourceCode,form.sourceEnvironment,form.weightMode],()=>{candidates.value=[];form.selectedCheckpoints=[];scanError.value='';scanned.value=false})
async function scan(){if(scanning.value)return;scanning.value=true;scanError.value='';scanned.value=false;candidates.value=[];form.selectedCheckpoints=[];const source=form.sourceWeights;try{if(!source.trim())throw new Error('请先填写实验 Checkpoints 根目录。');const result=await scanModelCheckpoints({sourceWeights:source});if(source!==form.sourceWeights)return;if(!Array.isArray(result.checkpoints))throw new Error('扫描接口返回格式不正确，请重启后端服务。');candidates.value=result.checkpoints;scanned.value=true;if(!candidates.value.length)scanError.value='未找到权重文件。支持所填目录及其直接子目录中的 safetensors、bin、pt、pth、ckpt 或 JAX params 目录。'}catch(e){scanError.value=e instanceof Error&&e.name==='TimeoutError'?'扫描超过 15 秒，请检查服务与挂载盘。':e instanceof Error?e.message:'扫描失败'}finally{scanning.value=false}}

const phases=computed(()=>current.value?.mode==='transfer'?['checking','scanning','copying']:['cloning','downloading','analyzing','installing','checking'])
const phaseIndex=computed(()=>phases.value.indexOf(current.value?.status??''))
async function poll(){if(disposed||!current.value)return;try{current.value=await getModelImport(current.value.id);error.value='';if(current.value.status==='ready')await store.syncImportedModels()}catch(e){error.value=e instanceof Error?e.message:'状态更新失败。'}finally{if(!disposed&&current.value&&importActive(current.value.status))timer=setTimeout(poll,1800)}}
async function load(){clearTimeout(timer);error.value='';try{const data=await listModelImports();root.value=data.root;available.value=true;if(typeof route.query.import==='string'){current.value=await getModelImport(route.query.import);if(importActive(current.value.status))timer=setTimeout(poll,1000)}else current.value=null}catch(e){available.value=false;error.value=e instanceof Error?e.message:'导入服务不可用。'}}
onMounted(load);watch(()=>route.query.import,load);onBeforeUnmount(()=>{disposed=true;clearTimeout(timer)})
async function submit(){if(busy.value)return;busy.value=true;error.value='';try{current.value=await createModelImport({...form});await router.replace({path:'/models/new',query:{import:current.value.id}})}catch(e){error.value=e instanceof Error?e.message:'创建失败。'}finally{busy.value=false}}
async function action(type:'retry'|'cancel'){if(!current.value||busy.value)return;busy.value=true;error.value='';try{current.value=await controlModelImport(current.value.id,type);clearTimeout(timer);timer=setTimeout(poll,500)}catch(e){error.value=e instanceof Error?e.message:'操作失败。'}finally{busy.value=false}}
</script>
<template><div class="page-heading"><div><div class="eyebrow">ROBOTIC LAB / 模型管理</div><h1>{{current?'模型导入':'新建模型'}}<span class="heading-dot">.</span></h1><p>下载并配置新模型，或复制云端已有模型并复用原环境。</p></div><button class="button" @click="router.push('/models')">返回模型管理</button></div><div class="import-mode">真实导入 · 文件将保存到当前服务所在容器；训练功能仍为 Mock。</div><div v-if="error" class="form-error" role="alert">{{error}} <button v-if="!current" class="text-link" @click="load">重新连接</button></div>
<form v-if="!current" class="import-form" @submit.prevent="submit"><div class="form-grid"><label>模型来源<select v-model="form.mode" :disabled="busy"><option value="add">增加模型</option><option value="transfer">转移模型</option></select></label><label class="wide">模型名称<input v-model="form.name" placeholder="例如：Pi0.5 项目环境" required maxlength="80"/></label><template v-if="form.mode==='add'"><label class="wide">GitHub 代码仓库<input v-model="form.github" type="url" placeholder="https://github.com/owner/repository" required/><small>填写公开仓库首页，服务会拉取默认分支。</small></label><label class="wide">Hugging Face / ModelScope 权重仓库<input v-model="form.weights" type="url" placeholder="https://huggingface.co/owner/model" required/><small>也支持 https://modelscope.cn/models/owner/model，填写仓库首页。</small></label><label>权重版本（可选）<input v-model="form.revision" placeholder="默认版本 / 分支 / commit"/></label><label>基础 Python<select v-model="form.python"><option value="python3">容器默认 python3</option><option>python3.10</option><option>python3.11</option><option>python3.12</option><option>python3.13</option></select><small>需已安装在容器内；不会替换系统 Python。</small></label></template><template v-else><label>云端代码目录<input v-model="form.sourceCode" required placeholder="/mnt/data/models/pi05/code"/><small>复制目录内容，保留原文件。</small></label><label>权重来源<select v-model="form.weightMode"><option value="base">基础模型权重</option><option value="checkpoints">已有训练 Checkpoints</option><option value="none">不导入权重（从零训练需脚本支持）</option></select></label><label v-if="form.weightMode!=='none'">{{form.weightMode==='checkpoints'?'实验 Checkpoints 根目录':'基础权重目录'}}<input v-model="form.sourceWeights" required placeholder="/mnt/data/models/pi05/weights"/></label><label>已有环境目录<input v-model="form.sourceEnvironment" required placeholder="/mnt/data/models/pi05/env"/><small>填写包含 bin/python 的 env 目录；复用原路径，不复制或安装依赖。</small></label><div v-if="form.weightMode==='checkpoints'"><button type="button" class="button" :disabled="scanning||busy" @click="scan">{{scanning?'扫描中…':'扫描 Checkpoints'}}</button><p v-if="scanning" role="status">正在扫描当前服务所在机器的目录，请稍候…</p><p v-if="scanError" class="form-error" role="alert">{{scanError}}</p><p v-else-if="scanned" role="status">扫描完成，找到 {{candidates.length}} 个版本。</p><p class="muted">已选 {{form.selectedCheckpoints.length}} 个版本 · {{(candidates.filter(c=>form.selectedCheckpoints.includes(c.name)).reduce((n,c)=>n+c.size,0)/1024**3).toFixed(2)}} GB 权重</p><p class="muted">按权重文件识别所填目录及直接子目录，支持 best、latest 等名称。仅做结构检查，未验证张量兼容性。</p><label v-for="cp in candidates" :key="cp.name" class="checkpoint-choice"><input v-model="form.selectedCheckpoints" type="checkbox" :value="cp.name" :disabled="!cp.complete"/>{{cp.name==='.'?'当前目录':cp.name}} · {{cp.step===null?'步数未知':'Step '+cp.step}} · {{cp.format}} · {{(cp.size/1024**3).toFixed(2)}} GB · {{cp.resumable?'含恢复文件':'仅权重 / 不完整'}}<small>{{cp.note}}</small></label></div></template></div><div class="import-destination"><strong>模型管理目录</strong><code>{{root}}</code><p v-if="form.mode==='add'">每个模型独立保存：code/ 代码、weights/ 权重、.venv/ 环境、import.json 导入记录。</p><p v-else>代码与权重复制到独立 code/、weights/ 目录，环境继续使用原 env 路径。</p></div><div v-if="form.mode==='add'" class="import-policy"><p>提交后自动下载代码和完整权重，并在独立虚拟环境内执行 README 中可识别的 pip 安装步骤。安装过程会运行仓库的 Python 安装代码，请使用可信仓库。</p><p>涉及 Conda、CUDA、系统依赖或自定义脚本的步骤会暂停自动配置并显示处理说明。私有或受限权重需提前在服务端配置访问凭据。</p></div><div v-else class="import-policy"><p>只支持当前云容器内的目录。默认允许 /mnt/data，可通过 MODEL_TRANSFER_ROOTS 配置其他源目录。仅使用可信环境：校验会运行该环境的 Python。</p><p>原 env 不会移动或修改；请保留原环境和原代码，editable 依赖可能仍指向原目录。代码复制排除 checkpoints、wandb、环境、缓存和日志；仅复制选中的权重版本。其他符号链接仍需处理。无 pip 环境允许接入，但依赖一致性未验证。校验通过不代表已验证训练。</p></div><div class="form-actions"><span class="muted">权重下载可能占用较大磁盘空间。</span><button class="button primary" :disabled="busy||scanning||!available||(form.mode==='transfer'&&form.weightMode==='checkpoints'&&!form.selectedCheckpoints.length)">{{busy?'正在创建…':form.mode==='transfer'?'开始转移模型':'开始导入并配置'}}</button></div></form>
<template v-else><div class="import-title"><div><h2>{{current.name}}</h2><span :class="['import-status',current.status]">{{importLabels[current.status]??current.status}}</span></div><div class="row-actions"><button v-if="importActive(current.status)" class="button danger" :disabled="busy" @click="action('cancel')">取消导入</button><button v-else-if="current.status!=='ready'" class="button" :disabled="busy" @click="action('retry')">重试导入</button><button v-else class="button primary" @click="router.push('/models')">查看模型</button></div></div><div class="import-phases"><span v-for="(phase,index) in phases" :key="phase" :class="{current:phaseIndex===index,done:current.status==='ready'||phaseIndex>index}"><b>{{index+1}}</b>{{importLabels[phase]}}</span></div><div v-if="current.error" class="form-error">{{current.error}}<p v-if="current.status==='needs_attention'">代码和权重已保留，请按下方 README 完成未支持的步骤。不会将此环境标为就绪。</p></div><p v-if="current.progress" role="status">已复制 {{current.progress.copiedFiles}} / {{current.progress.totalFiles}} 个文件 · {{current.progress.totalBytes?Math.floor(current.progress.copiedBytes/current.progress.totalBytes*100):0}}%</p><p v-if="current.mode==='transfer'" class="import-mode">复用原环境，请保留原环境及其 editable 依赖引用的原代码目录。</p><p v-if="current.environmentCheck" class="import-mode">{{current.environmentCheck}}</p><div v-for="cp in current.importedCheckpoints" :key="cp.name" class="import-mode">已导入 {{cp.name==='.'?'当前目录':cp.name}} · {{cp.step===null?'步数未知':'Step '+cp.step}} · {{cp.format}} · {{cp.resumable?'含恢复状态文件':'仅模型参数'}} · {{cp.path}}</div><dl class="review-grid"><div v-if="current.mode==='transfer'"><dt>原代码目录</dt><dd>{{current.sourceCode}}</dd></div><div v-if="current.mode==='transfer'"><dt>原权重目录</dt><dd>{{current.sourceWeights}}</dd></div><div v-if="current.mode!=='transfer'"><dt>代码仓库</dt><dd><a :href="current.github.replace(/\.git$/,'')" target="_blank" rel="noreferrer">{{current.github}}</a></dd></div><div v-if="current.mode!=='transfer'"><dt>权重仓库</dt><dd><a :href="current.weights" target="_blank" rel="noreferrer">{{current.weights}}</a></dd></div><div><dt>代码目录</dt><dd>{{current.paths.code??'等待创建'}}</dd></div><div><dt>权重目录</dt><dd>{{current.paths.weights??'等待创建'}}</dd></div><div><dt>Python 环境</dt><dd>{{current.paths.environment??'等待创建'}}</dd></div><div v-if="current.mode!=='transfer'"><dt>Git commit</dt><dd>{{current.commit??'等待拉取'}}</dd></div></dl><section class="panel" style="margin-top:22px"><div class="log-head"><h2>导入日志</h2><span class="muted">{{importActive(current.status)?'自动更新':'已停止更新'}} · 最近 400 行</span></div><pre class="log-terminal">{{current.logs.join('\n')||'正在等待服务响应…'}}</pre></section><section v-if="current.plan" class="readme-plan"><h2>README 环境配置</h2><p>识别到的标准安装步骤：</p><pre class="command-preview">{{current.plan.commands.map(c=>c.label).join('\n')||'无可自动执行步骤'}}</pre><template v-if="current.plan.unsupported.length"><p>以下步骤需人工处理，自动安装未执行：</p><pre class="command-preview">{{current.plan.unsupported.join('\n')}}</pre></template><details><summary>查看 {{current.readmeFile||'README'}} 原文</summary><pre class="readme-text">{{current.readme||'仓库根目录未找到 README。'}}</pre></details></section></template></template>
<style scoped>.checkpoint-choice{display:flex;align-items:center;flex-wrap:wrap;gap:10px;margin-top:14px;font-size:12px}.checkpoint-choice input{width:auto}.checkpoint-choice small{width:100%;color:var(--muted)}.import-form .form-grid,.review-grid{grid-template-columns:minmax(0,1fr)}.import-form .form-grid .wide{grid-column:auto}.import-mode{font-size:11px;color:#8a6c35;margin-bottom:24px}.import-form{max-width:850px;border-top:1px solid var(--border);padding-top:24px}.import-destination{margin:24px 0;border-top:1px solid var(--border);border-bottom:1px solid var(--border);padding:17px 0;font-size:12px}.import-destination strong{display:block;margin-bottom:9px;font-weight:500}.import-destination code{font-size:11px;overflow-wrap:anywhere}.import-destination p,.import-policy p{font-size:11px;line-height:1.9;color:var(--muted);margin-top:9px}.form-actions>span{font-size:10px}.form-actions button:disabled{opacity:.5}.import-title{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:22px}.import-title>div:first-child{display:flex;gap:15px;align-items:center}.import-title h2{font-size:19px}.import-status{font-size:11px;color:var(--blue)}.import-status.failed,.import-status.needs_attention{color:#bd624c}.import-status.ready{color:#31a180}.import-phases{display:flex;gap:15px;flex-wrap:wrap;padding:18px 0;border-top:1px solid var(--border);border-bottom:1px solid var(--border);margin-bottom:20px}.import-phases span{display:flex;align-items:center;gap:8px;font-size:11px;color:var(--muted);flex:1;white-space:nowrap}.import-phases b{display:grid;place-items:center;border:1px solid var(--border);border-radius:50%;width:24px;height:24px;font-weight:400}.import-phases .current{color:var(--blue)}.import-phases .current b{border-color:var(--blue)}.import-phases .done{color:#31a180}.review-grid a{color:var(--blue)}.readme-plan{margin-top:25px}.readme-plan h2{font-size:15px}.readme-plan p{font-size:12px;color:var(--muted);margin:15px 0}.readme-plan summary{font-size:12px;cursor:pointer}.readme-text{white-space:pre-wrap;overflow-wrap:anywhere;font:11px/1.8 ui-monospace,monospace;padding:20px;background:var(--subtle);border:1px solid var(--border);border-radius:7px;max-height:500px;overflow:auto}@media(max-width:700px){.import-title{flex-wrap:wrap}.import-title>div:first-child{flex-wrap:wrap}.import-phases span{flex:1 0 40%}}</style>
